soldierThrowGrenade=function(body:MovieClip):Void {
    if(!this.soldierCanAct(body))return;
    var owner:Object=this.soldierAttackOwner;
    if(owner.thrown)return;
    owner.thrown=true;
    var data:Object=_root.getItemData(owner.itemName).data;
